using System;
using System.IO;
using System.Linq;
using UnityEngine;
using MaritimeLegend.Domain;
using GUI=MaritimeLegend.LiveGui;
using GUIUtility=MaritimeLegend.LiveGuiUtility;
namespace MaritimeLegend {
public partial class MaritimeGame {
internal CityScene currentCity;
public void WalkTo(ICityInteraction target){walkTarget=target.Position+new Vector2(60,60);walkAction=target.Destination;sound.Cue(3);}

internal void City(){if(currentCity.Diorama!=null){RefinedCity();return;}GUI.DrawTexture(new Rect(28,128,1460,760),currentCity.Current.background,ScaleMode.ScaleAndCrop);Fill(new Rect(28,128,1460,100),new Color(.02f,.07f,.08f,.55f));Label(60,150,1000,60,c.ports[s.city].name+"  /  家族的港湾",heading);foreach(var point in currentCity.Interactions){var p=point.Position;if(Btn(p.x,p.y,190,54,point.Label))point.Interact(this);}Avatar(new Rect(characterPos.x,characterPos.y,48,90),s.appearance,Vector2.Distance(characterPos,walkTarget)>2?Mathf.Sin(Time.time*12)*3:0);if(Input.GetMouseButtonDown(0)&&!LiveGui.PointerOverControl&&new Rect(30,230,1450,650).Contains(LiveGui.Mouse)){walkTarget=LiveGui.Mouse;walkAction="";sound.Cue(4);}Panel(new Rect(1510,130,380,755));Label(1540,160,320,60,"港口记事",heading);Label(1540,245,315,210,c.ports[s.city].trait+"\n\n本城声望 "+s.cities[s.city].reputation+"\n产业许可证："+(s.cities[s.city].license?"已开放":"未签发"));Label(1540,490,310,200,c.quests[s.chapter-1].title+"\n"+c.quests[s.chapter-1].description,small);Label(1540,745,315,100,"点击地点，角色走近后进入。\n也可使用下方快捷入口。",small);}
internal void MarketUI(){OpenTradePanel();}
internal void TownHall(){Panel(new Rect(60,145,1120,715));Label(100,185,1020,65,"市政厅 · 诸港的契约",heading);int foreign=s.cities.Count(x=>x.license)-1;Label(100,295,990,140,"产业许可："+(s.cities[s.city].license?"已经签发":"待申请")+"\n本城声望 "+s.cities[s.city].reputation+"  /  申请要求 "+Math.Min(20,foreign*5)+"\n许可基价 "+(300+foreign*200)+" 金币（外交伙伴可减免）");if(Btn(100,470,550,70,"申请产业许可证"))Notify(g.License());var p=c.products[s.contractProduct];Label(100,590,950,100,"商会急单："+p.name+" ×"+s.contractQuantity+"\n剩余游戏时间 "+Math.Max(0,s.contractDeadline-s.worldHours).ToString("0.0")+" 小时；请从船舱交付。");if(Btn(100,730,550,65,"交付委托 / 到期换单"))Notify(g.Contract());GUI.DrawTexture(new Rect(1240,180,560,680),portrait,ScaleMode.ScaleToFit);}
internal void Partners(){Panel(new Rect(30,130,1860,755));Label(65,150,1680,60,"酒馆 · 同舟之人",heading);Label(65,220,1600,40,"当班岗位 "+s.partners.Count(x=>x.active)+" / "+c.ships[s.ships[0].type].slots+"  ·  伙伴每次有效航行帮助提升技能；研修提高信赖。",small);var people=c.partners.Where(p=>p.port==s.city||s.partners.Any(x=>x.id==p.id)).ToArray();scroll=GUI.BeginScrollView(new Rect(55,290,1790,555),scroll,new Rect(0,0,1740,people.Length*155));for(int i=0;i<people.Length;i++){var p=people[i];var ps=s.partners.FirstOrDefault(x=>x.id==p.id);float y=i*155;Label(10,y,940,43,p.name+"  /  "+p.role+(ps==null?"":"  /  信赖"+ps.trust));Label(10,y+46,1000,35,p.specialty+"  ·  "+p.skill1+" / "+p.skill2,small);Label(10,y+87,1000,55,p.bio,small);if(ps==null){if(Btn(1160,y+24,500,65,"招募 · "+p.fee+"金币"))Notify(g.Recruit(p.id),8);}else{if(Btn(1120,y+25,240,60,ps.active?"当班 → 待命":"待命 → 当班"))Notify(g.TogglePartner(p.id));if(Btn(1380,y+25,310,60,"研修 · "+ps.trust*150+"金币"))Notify(g.TrainPartner(p.id));}}GUI.EndScrollView();}
internal void Shipyard(){Panel(new Rect(30,130,1860,755));Label(65,150,1680,60,"船坞 · 风帆与远方",heading);if(Btn(1050,155,360,56,"修理船体与风帆"))Notify(g.Repair());if(Btn(1450,155,360,56,"补满食水与弹药"))Notify(g.Supply());for(int i=0;i<c.ships.Length;i++){var d=c.ships[i];float x=60+i*448;Panel(new Rect(x,260,425,240));Label(x+20,280,380,50,d.name);Label(x+20,340,380,80,"载货 "+d.capacity+"  炮位 "+d.guns+"\n航速 "+d.speed+"  岗位 "+d.slots,small);if(Btn(x+20,427,380,55,"购入 · "+d.price+"金币"))Notify(g.BuyShip(i));}scroll=GUI.BeginScrollView(new Rect(60,545,1780,295),scroll,new Rect(0,0,1730,s.ships.Count*95));for(int i=0;i<s.ships.Count;i++){var sh=s.ships[i];float y=i*95;Label(10,y+15,1180,55,(i==0?"[旗舰] ":"")+c.ships[sh.type].name+" · Lv"+sh.level+"  船体 "+sh.hull.ToString("0")+"  帆 "+sh.sails.ToString("0")+"  食水 "+sh.food.ToString("0")+"  "+(sh.busy?"运输中":"停泊"));if(Btn(1230,y+8,240,55,"设为旗舰",i>0&&!sh.busy))Notify(g.Flagship(i));if(Btn(1490,y+8,230,55,"升级 · "+c.balance.upgrades.shipPrice+"金",sh.level<c.balance.upgrades.shipMaxLevel&&!sh.busy)){Notify(g.UpgradeShip(i));}}GUI.EndScrollView();}
internal void Quests(){Panel(new Rect(50,135,1820,750));Label(85,160,1710,60,"第"+s.chapter+"章 · "+c.quests[s.chapter-1].title,heading);Label(90,245,1670,90,c.quests[s.chapter-1].description);string checklist="已交易 "+s.trades+" 次  /  已完工 "+s.produced+" 单  /  产业园 "+s.cities.Count(x=>x.license)+" 城  /  航线 "+s.routes.Count+" 条\n\n两港品质材料："+(s.materialsSubmitted?"已提交":"待提交")+"\n品质2以上旗舰航海仪："+(s.instrumentMade?"已制造":"待制造")+"\n船帆制造："+(s.sailsMade?"已制造":"待制造")+"\n非初始型号旗舰："+(s.ships[0].type>0?"具备":"未具备")+"  /  信赖2级当班伙伴："+(s.partners.Any(x=>x.active&&x.trust>=2)?"具备":"未具备");Label(90,360,1040,340,checklist);if(Btn(1180,370,610,70,"提交两港的品质2木板、布匹"))Notify(g.SubmitMaterials());if(Btn(1180,470,610,70,"开启最终航程 → 杭州")){Notify(g.BeginFinal());if(s.atSea)page="航海";}if(Btn(1180,570,610,65,"海战演练",s.mode=="经典"))StartBattle(false);Label(1180,675,605,150,"建议：先完成家园原料加工，再运货至邻港。\n升级工坊和工艺可提高品质；材料在不同城市生产会记录各自产地。",small);}
internal void Details(){Panel(new Rect(35,130,1850,755));Label(65,150,1000,55,s.name+" · 家族账本",heading);for(int i=0;i<c.skills.Length;i++)Label(65+(i%3)*280,230+(i/3)*65,260,50,c.skills[i].id+" Lv"+s.skillLevels[i]);Label(950,165,840,50,"自动舰队 / 日志",heading);scroll=GUI.BeginScrollView(new Rect(950,230,880,605),scroll,new Rect(0,0,835,s.autoRoutes.Count*170+s.journal.Count*90));int row=0;foreach(var a in s.autoRoutes.ToArray()){float y=row++*170;Label(0,y,820,62,c.ports[a.from].name+" → "+c.ports[a.to].name+"  "+a.status+"  "+(a.progress*100).ToString("0")+"%\n累计盈亏 "+a.profit+"  "+a.reason,small);if(Btn(0,y+85,230,50,a.status=="暂停"?"继续":"暂停")){if(a.status=="暂停")g.ResumeAuto(a);else g.StopAuto(a);}if(Btn(250,y+85,230,50,"解除并卸货"))Notify(g.DeleteAuto(a));}for(int i=0;i<s.journal.Count;i++)Label(0,row*170+i*90,825,84,s.journal[i],small);GUI.EndScrollView();Avatar(new Rect(280,545,140,250),s.appearance,0);}
internal void Ending(){Panel(new Rect(150,160,1620,700));Label(350,215,1260,100,"传 奇 航 路 建 立",new GUIStyle(heading){fontSize=64});Label(360,370,1190,160,"旧海图的最后一处空白，写上了你和伙伴们的名字。\n诸港的工坊在晨光中点火，装满货物的船只沿约定的航线起航。\n这不是一个人的黄金时代，而是一个家族守住的承诺。");Label(360,550,1190,130,string.Join("、",s.partners.Select(p=>c.partners[p.id].name))+"\n每一位同舟者，都在这张海图上留下了自己的归途。",small);if(Btn(540,730,840,75,"保存通关档 · 继续自由经营")){Save(false);page="城市";}}
}}
